def tag(title,description,slug,content):
    (ROOT/slug).write_text(BASE.render(title=title,description=description,slug=slug,content=content,product_nav=PRODUCT_NAV,year=2026,json_ld=json.dumps(ORG,ensure_ascii=False)),encoding='utf-8')

def e(s): return escape(str(s),quote=True)
def img(id,alt='',cls='',loading='lazy'):
    return f'<img src="{e(IMAGES[id])}" alt="{e(alt)}" loading="{loading}" decoding="async" data-image-fallback="1" class="{cls}">'
def kicker(text):return f'<span class="kicker">{e(text)}</span>'
def button(label,href='kontakt.html#upit',kind='blue'):return f'<a class="btn btn--{kind} btn--arrow" href="{e(href)}">{e(label)}</a>'
def eyebrow(text):return f'<span class="eyebrow">{e(text)}</span>'
def card(name,description,photo,href):
    return f'<a class="service-card reveal" href="{e(href)}"><div class="service-card__image">{img(photo,name)}</div><div class="service-card__body"><h3>{e(name)}</h3><p>{e(description)}</p><span class="text-link">Saznajte više</span></div></a>'
def titlehero(title,description,crumb='Proizvodi',crumburl='proizvodi-digitron.html'):
    return f'<section class="page-hero"><div class="container"><div class="breadcrumbs"><a href="index.html">Početna</a><span>›</span><a href="{e(crumburl)}">{e(crumb)}</a><span>›</span><span>{e(title)}</span></div>{kicker("Digitron d.o.o. · Buje")}<h1>{e(title)}</h1><p>{e(description)}</p></div></section>'

